import java.util.*;
import java.io.*;

public class Main {

    static ArrayList<Long> divisors(long num) {
        ArrayList<Long> ret = new ArrayList<Long>();
        long i;
        for (i = 2; i * i < num; i++)
            if (num % i == 0) {
                ret.add(i);
                ret.add(num / i);
            }
        if (i * i == num)
            ret.add(i);
        return ret;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer in = new StreamTokenizer(br);
        StringBuilder sb = new StringBuilder();
        while (in.nextToken() != StreamTokenizer.TT_EOF) {
            long n = (long) in.nval;
            in.nextToken();
            long m = (long) in.nval;
            in.nextToken();
            long k = (long) in.nval;

            if (n % 2 == 0) {
                sb.append("Marsel\n");
                continue;
            }
            ArrayList<Long> div = divisors(m);
            boolean flag = false;
            if (m > 1)
                div.add(1L);
            for (int i = 0; i < div.size() && !flag; i++)
                if (div.get(i) >= k)
                    flag = true;
            if (flag)
                sb.append("Timur\n");
            else
                sb.append("Marsel\n");
        }
        System.out.print(sb);
    }
}

